# Additional local change: full FP32 router/top-8 fusion for 1..8 tokens; no activation or weight quantization.
import time as _pd_time, threading as _pd_thr
_PD_T0 = _pd_time.perf_counter()
_PD_BUILDS = []
_PD_STAGES = []
def _pd_stage(label):
    _PD_STAGES.append((label, _pd_time.perf_counter() - _PD_T0))
def _pd_wrap(fn, namefn):
    def w(*a, **k):
        s = _pd_time.perf_counter() - _PD_T0
        ok = False
        try:
            r = fn(*a, **k)
            ok = True
            return r
        finally:
            try:
                _PD_BUILDS.append((str(namefn(a, k)), _pd_thr.current_thread().name, s, _pd_time.perf_counter() - _PD_T0, ok))
            except Exception:
                pass
    return w
import torch.utils.cpp_extension as _pd_cppext
_pd_cppext.load_inline = _pd_wrap(_pd_cppext.load_inline, lambda a, k: a[0] if a else k.get('name'))
if hasattr(_pd_cppext, 'load'):
    _pd_cppext.load = _pd_wrap(_pd_cppext.load, lambda a, k: a[0] if a else k.get('name'))
