from typing import TypedDict
import torch
from torch.utils.cpp_extension import load_inline

class _native_moe_Weights(TypedDict):
 w13: torch.Tensor
 w13_sf: torch.Tensor
 w13_gs: torch.Tensor
 w2: torch.Tensor
