def _native_attn__launch(data, dbg=None, _mod=None, pdl=None, **override):
 cfg = data['config']
 (B, L) = (cfg['batch'], cfg['q_len'])
 (hq, hkv, d, P) = (cfg['num_q_heads'], cfg['num_kv_heads'], cfg['head_dim'], cfg['page_size'])
 qkv = data['qkv']
 device = qkv.device
