def cpssm_c12_unpack(data, base, esc):
 (r, c) = data.shape[:2]
 dev = data.device
 p = data.view(r, c, 3, 32, 16)
 lo = torch.cat([p[:, :, 0], p[:, :, 1]], dim=-1).to(torch.int32)
 code = p[:, :, 2].contiguous().view(torch.int32).view(r, c, 32, 4).long() & 4294967295
