 pos = torch.tensor(CPSSM_SIGN_POS, device=dev).long()
 d = (code[..., None] >> nib & 7).reshape(r, c, 32, 32)
 sg = (code[..., None] >> pos & 1).reshape(r, c, 32, 32)
 val = (sg << 15 | base + d << 8).to(torch.int32) | lo
