def tt_v10_tune_build(configs: list):
 for c in configs:
  (bn, wg, st, pack, split, push, pw, px, hint, order, sw, prod) = c
  assert bn in (128, 192, 256) and wg in (1, 2) and (st >= 2) and (split in (1, 2, 3, 4))
  assert st * ((64 * wg + bn) * 128 + 16) + 16 <= 227328
