 sign = hi >> 7
 hist = torch.bincount(e71.flatten(), minlength=128)
 win = torch.stack([hist[b:b + 8].sum() for b in range(121)])
 base = int(win.argmax())
 o = (e71 - base).clamp(0, 7)
